using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using UnityEngine;
namespace AgentHands {
public static class DirectPlanParser {
 public static GesturePlan Parse(string raw,RegisteredObject[] registry,Vector3 head,float duration){
 var plan=new GesturePlan{tagged=raw,responseDuration=duration,objects=registry,response=Regex.Replace(raw,@"\[[^\]]*\]",""),alignment="word-position heuristic, not forced alignment"};var wordMatches=Regex.Matches(plan.response,@"\S+");plan.wordStarts=new float[wordMatches.Count];float total=0;var weights=new float[wordMatches.Count];for(int w=0;w<weights.Length;w++){string token=wordMatches[w].Value;weights[w]=Mathf.Max(1,token.Trim('.',',','!','?',';',':').Length)+(".!?;:".Contains(token[token.Length-1].ToString())?3:0);total+=weights[w];}float elapsed=0;for(int w=0;w<weights.Length;w++){plan.wordStarts[w]=elapsed/Mathf.Max(1,total)*duration;elapsed+=weights[w];}if(wordMatches.Count==0)throw new ArgumentException("Generated response has no spoken words");var objects=new List<RegisteredObject>(registry);objects.Add(new RegisteredObject{id="agent-midair",label="Agent gesture space",position=new[]{head.x,head.y-.25f,head.z+.65f},size=new[]{.18f,.18f,.1f}});plan.objects=objects.ToArray();var events=new List<GestureEvent>();int removed=0,sequence=0;float lastLeft=-1,lastRight=-1;foreach(Match m in Regex.Matches(raw,@"\[([A-Za-z0-9]+)(?:;([^\[\]]*))?\]")){var attrs=new Dictionary<string,string>();foreach(var part in m.Groups[2].Value.Split(',')){int i=part.IndexOf(':');if(i>0)attrs[part.Substring(0,i).Trim()]=part.Substring(i+1).Trim();}foreach(var attr in attrs){string allowed;switch(attr.Key){case "object":case "target":case "region":case "spatiality":continue;case "handedness":allowed="single,double";break;case "gesture":allowed="palm,fist,point,hold,grab,thumbUp,thumbDown,one,two,three,cylinder,cube,sphere";break;case "dynamics":allowed="static,rollRotation,pitchRotation,yawRotation,xTranslation,yTranslation,zTranslation";break;case "interactivity":allowed="none,highFive,shakeHand,holdHand";break;case "vfx":allowed="none,burn,freeze,glow,poisoned,spoil,explode";break;default:throw new ArgumentException("Unknown gesture attribute "+attr.Key);}if(Array.IndexOf(allowed.Split(','),attr.Value)<0)throw new ArgumentException("Invalid gesture attribute "+attr.Key);}
 string kind=m.Groups[1].Value,target=attrs.ContainsKey("object")?attrs["object"]:attrs.ContainsKey("target")?attrs["target"]:"agent-midair";int word=0;while(word+1<wordMatches.Count&&wordMatches[word].Index+wordMatches[word].Length<=m.Index-removed)word++;float start=plan.wordStarts.Length>0?plan.wordStarts[word]:0;
 if(attrs.ContainsKey("spatiality")&&attrs["spatiality"]!="midAir"){var spatial=attrs["spatiality"];if(Array.Exists(registry,o=>o.id==spatial))target=spatial;else{var grid=Regex.Match(spatial,@"^(.*)_([FBTDLR])_(top|middle|center|bottom)_(left|center|right)$");if(!grid.Success)throw new ArgumentException("Unresolved spatiality");target=grid.Groups[1].Value;attrs["region"]=grid.Groups[2].Value+":"+grid.Groups[3].Value.Replace("middle","center")+":"+grid.Groups[4].Value;}}
 if(attrs.ContainsKey("region")){var o=Array.Find(registry,x=>x.id==target);if(o==null)throw new ArgumentException("Unresolved region object");var region=attrs["region"].Split(':');if(region.Length!=3)throw new ArgumentException("Invalid semantic region");float u=region[2]=="left"?-1f/3:region[2]=="right"?1f/3:region[2]=="center"?0:float.NaN,v=region[1]=="bottom"?-1f/3:region[1]=="top"?1f/3:region[1]=="center"?0:float.NaN;Vector3 local;switch(region[0]){case "F":local=new Vector3(u,v,.5f);break;case "B":local=new Vector3(-u,v,-.5f);break;case "L":local=new Vector3(-.5f,v,u);break;case "R":local=new Vector3(.5f,v,-u);break;case "T":local=new Vector3(u,.5f,-v);break;case "D":local=new Vector3(u,-.5f,v);break;default:throw new ArgumentException("Invalid semantic region face");}if(float.IsNaN(u)||float.IsNaN(v))throw new ArgumentException("Invalid semantic region grid");var position=o.Position+Vector3.Scale(local,o.Size);target=o.id+"-region-"+sequence;objects.Add(new RegisteredObject{id=target,label=o.label+" region",position=new[]{position.x,position.y,position.z},size=new[]{.025f,.025f,.025f},registration="native axis-aligned semantic grid; no inferred rotation"});}
removed+=m.Length;string gesture;switch(kind){case "PointObject":case "RegionOfObject":gesture="point";break;case "DirectionOfObject":gesture="trace";break;case "Action":gesture="grasp";break;case "ObjectProxy":gesture="rotate";break;case "Comparison":case "Geometry1D":case "Geometry2D":case "Geometry3D":gesture="measure";break;case "Attention":case "Prohibition":case "StopExpression":gesture="beat";break;case "Positive":case "ThumbupExpression":case "Negative":case "Numeric":case "Celebration":case "Burn":case "BurnEffect":case "Poisoned":case "Spoil":gesture="open";break;default:throw new ArgumentException("Unsupported GestureEvent "+kind);}
 string pose=attrs.ContainsKey("gesture")?attrs["gesture"]:gesture=="point"?"point":"palm";if(kind=="Positive"||kind=="ThumbupExpression")pose="thumbUp";if(kind=="Negative")pose="thumbDown";bool both=attrs.ContainsKey("handedness")&&attrs["handedness"]=="double"||gesture=="measure";string hand=both?"both":lastLeft<=lastRight?"left":"right";foreach(var prior in events){if(prior.start+prior.duration>start&&(prior.hand==hand||prior.hand=="both"||hand=="both"))prior.duration=Mathf.Max(.001f,start-prior.start);}if(hand=="left"||hand=="both")lastLeft=start;if(hand=="right"||hand=="both")lastRight=start;events.Add(new GestureEvent{id="event-"+sequence++,wordIndex=word,paperEvent=kind,targetId=target,start=start,duration=Mathf.Max(.05f,Mathf.Min(2.5f,duration-start)),hand=hand,gesture=gesture,pose=pose,motion=attrs.ContainsKey("dynamics")?attrs["dynamics"]:"static",effect=attrs.ContainsKey("vfx")?attrs["vfx"]:kind=="Burn"||kind=="BurnEffect"?"burn":kind=="Poisoned"?"poisoned":kind=="Spoil"?"spoil":"none",interactivity=attrs.ContainsKey("interactivity")?attrs["interactivity"]:kind=="Celebration"?"highFive":"none",speech=plan.response});}
 plan.objects=objects.ToArray();plan.events=events.ToArray();return plan;
 }
}
}
